import{_ as a,o as t,c as e,a2 as l}from"./chunks/framework.XctAhZuT.js";const u=JSON.parse('{"title":"Anki 集成","description":"Turna 内嵌官方 Anki 内核（Rust 编写，经 FFI 调用）。.apkg 导入后由 Official Collection 持有 note、card、revlog 与正式调度状态。Android arm64 与 iOS 走同一条…","frontmatter":{"description":"Turna 内嵌官方 Anki 内核（Rust 编写，经 FFI 调用）。.apkg 导入后由 Official Collection 持有 note、card、revlog 与正式调度状态。Android arm64 与 iOS 走同一条…"},"headers":[],"relativePath":"guide/anki.md","filePath":"guide/anki.md","lastUpdated":1790697640000}'),r={name:"guide/anki.md"};function o(d,i,n,c,s,f){return t(),e("div",null,[...i[0]||(i[0]=[l('<h1 id="anki-集成" tabindex="-1">Anki 集成 <a class="header-anchor" href="#anki-集成" aria-label="Permalink to &quot;Anki 集成&quot;">​</a></h1><p>Turna 内嵌官方 Anki 内核（Rust 编写，经 FFI 调用）。<code>.apkg</code> 导入后由 Official Collection 持有 note、card、revlog 与正式调度状态。Android arm64 与 iOS 走同一条生产路径（iOS 为静态链接 rslib + WKWebView 复习器）。<code>.colpkg</code> 当前不属于生产导入合同。</p><div class="warning custom-block"><p class="custom-block-title">验收状态</p><p>Official Anki 当前口径是**「验收 NO-GO；迁移中」**。</p><ul><li>Android 写侧链路（导入→账本→视图→删除收敛）曾于 2026-09-02 在真机以 <strong>debug 构建</strong>证明成立；同夜暴露的一个课程装载缺陷已在代码层修复，但<strong>修后未在任何 Android 设备复跑</strong>。</li><li>iOS 侧于 2026-09-26 完成<strong>模拟器</strong> E2E（真 <code>.apkg</code> 导入 + 复习器渲染），非真机。</li><li><strong>生产 bundle 的完整用户流从未验证。</strong></li></ul><p>因此本文档不写「迁移完成」，也不写「Android 可正常使用」。两项限制仍开放未定：引擎生命周期耦合可能使物理删除延迟到下次导入；同 GUID 冲突的来源所有权策略尚未定案。</p></div><p>产品页演示见 <a href="./../../anki.html">anki.html</a>。</p><h2 id="数据所有权" tabindex="-1">数据所有权 <a class="header-anchor" href="#数据所有权" aria-label="Permalink to &quot;数据所有权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>所有者</th></tr></thead><tbody><tr><td>Official note / card / revlog</td><td>Official Collection</td></tr><tr><td>Official 正式评分</td><td>Official scheduler</td></tr><tr><td>课程树展示</td><td>从 Official 来源建立的投影</td></tr><tr><td>课程原生词汇与表达</td><td>Turna 课程数据库与 Dart FSRS</td></tr></tbody></table><p>两类项目可显示在统一复习入口，但不混写调度状态。Official runtime 不可用时，Official 来源必须 fail closed。</p><h2 id="导入阶段" tabindex="-1">导入阶段 <a class="header-anchor" href="#导入阶段" aria-label="Permalink to &quot;导入阶段&quot;">​</a></h2><ol><li>选择 <code>.apkg</code>。</li><li>生成一次导入执行计划。</li><li>检查 notetype 映射与预览。</li><li>写入 Official Collection。</li><li>建立课程投影与 source scope。</li><li>通过共享复习入口启动 Official review session。</li></ol><h2 id="渲染" tabindex="-1">渲染 <a class="header-anchor" href="#渲染" aria-label="Permalink to &quot;渲染&quot;">​</a></h2><ul><li>保真模板卡默认就经 WebView 渲染（Android / iOS），以保留原模板的 HTML、CSS 与脚本行为。</li><li>桌面与 Web 不实例化 WebView，降级为剥离标签的纯文本视图。</li><li>卡片网络被无条件阻断，无法通过设置放开；JavaScript 另有独立开关。两者权限不同，执行 JavaScript 不等于开放网络。</li><li>渲染失败依次降级，不能让复习停在空白卡。</li></ul><h2 id="数据在哪" tabindex="-1">数据在哪 <a class="header-anchor" href="#数据在哪" aria-label="Permalink to &quot;数据在哪&quot;">​</a></h2><p>牌组、媒体与复习记录保存在设备本地，不要求账号或 AnkiWeb。删除牌组、清缓存和清除应用数据是不同操作。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/docs/guide/anki-import">导入 Anki 牌组</a></li><li><a href="/docs/guide/anki-rendering">卡片渲染与网络隔离</a></li></ul>',15)])])}const p=a(r,[["render",o]]);export{u as __pageData,p as default};
